window.SERUMS_DATA["fichas"]=[{"id":"mortalidad-materna-084-227","match":"Resolución Ministerial N.° 272-2025-MINSA","code":"Directiva Sanitaria N.° 084-MINSA/2019/DGIESP + NTS N.° 227-MINSA/CDC-2025","title":"Comités de prevención y vigilancia de la muerte materna, fetal y neonatal","aprobada":"RM 251-2019/MINSA (Directiva 084) · RM 272-2025/MINSA (NTS 227)","eje":"Salud pública","estado":"REVIEW_REQUIRED","vigencia":"Vigencia de la Directiva 084 por confirmar en El Peruano. La NTS 227 deroga la Directiva 036 (RM 778-2016).","fuente":"","alerta":"La Directiva 084 NO fija los plazos de notificación ni de investigación. Esos plazos (24 h) están en la NTS 227-2025. Regla: clasificación y comités → 084; notificación, investigación y búsqueda activa → NTS 227.","linea":{"titulo":"Línea de tiempo de la muerte materna","tramos":[{"t":"Embarazo, parto y puerperio","s":"hasta 42 días","c":"verde","w":5},{"t":"Tardía","s":"42 días a 1 año · no entra a la tasa","c":"ambar","w":3},{"t":"Por secuelas","s":"más de 1 año","c":"gris","w":2}],"sellos":[{"t":"24 h","s":"Notificación (FNIMM) · NTS 227","c":"rojo"},{"t":"24 h","s":"Investigación (FIEMM) · NTS 227","c":"rojo"},{"t":"30 días","s":"Auditoría médica · Directiva 084","c":"azul"}],"nota":"Neonatal: precoz 0–7 días · tardía 7–28 días"},"definiciones":[["Muerte materna","Mujer embarazada o dentro de los 42 días siguientes a la terminación del embarazo, por causa relacionada o agravada por el embarazo o su manejo; no por causas accidentales o incidentales.","084 · pág. 5"],["Directa","Complicaciones obstétricas del embarazo, parto o puerperio, intervenciones, omisiones, tratamiento incorrecto o cadena de eventos derivada.","084 · pág. 5"],["Indirecta","Enfermedad previa o surgida en el embarazo, no obstétrica, agravada por los efectos fisiológicos del embarazo. Incluye el suicidio en embarazo, parto o puerperio.","084 · pág. 5"],["Incidental / accidental","Dentro de los 42 días, causa externa, no ligada al embarazo, parto o puerperio.","084 · pág. 5"],["Tardía","Causas obstétricas directas o indirectas después de los 42 días y antes de un año de terminado el embarazo.","084 · pág. 5"],["Institucional","En un establecimiento de salud (público o privado), sin importar el tiempo de permanencia; incluye traslado entre establecimientos y casas de espera.","084 · pág. 5"],["Extra-institucional (domiciliaria)","Fuera del establecimiento, o si la gestante o puérpera llega cadáver.","084 · pág. 5"],["Muerte perinatal","Desde las 22 semanas de gestación (o 500 g, o 25 cm) hasta los 7 días completos después del nacimiento.","084 · pág. 6"],["Muerte fetal","Antes de la expulsión, desde las 22 semanas o peso igual o mayor de 500 g.","084 · pág. 6"],["Muerte neonatal","Recién nacido vivo, desde el nacimiento hasta los 28 días completos. Precoz: primeros 7 días. Tardía: después del 7.º día, hasta los 28.","084 · pág. 6"]],"plazos":[{"norma":"Directiva 084 (comités)","filas":[["Reunión ordinaria, nivel nacional","Trimestral","pág. 8, 12"],["Reunión ordinaria, regional y demás niveles","Mensual","pág. 9, 12"],["Reunión extraordinaria","3 días de anticipación; se omite ante urgencia","pág. 12"],["Auditoría médica (hospital o instituto)","30 días de ocurrido el evento","pág. 10"],["Envío del hospital al nivel regional","Máximo 7 días hábiles de culminada la auditoría","pág. 10"],["Informe regional de auditoría al nivel nacional","Máximo 30 días calendario de ocurrida la muerte","pág. 9"],["Acta y conclusiones del regional al nacional","Máximo 10 días hábiles de la reunión","pág. 9"]]},{"norma":"NTS 227-2025 (vigilancia)","filas":[["Notificación de muerte materna (FNIMM)","Inmediata: dentro de las 24 h de ocurrido o conocido el evento","pág. 8"],["Investigación epidemiológica (FIEMM)","Dentro de las 24 h de haberse notificado","pág. 9"],["Ingreso de la investigación al aplicativo","30 días calendario desde la notificación (15 + 15)","pág. 10"],["Notificación negativa","Semanal, si no hubo muertes maternas","pág. 9"],["Búsqueda activa","Mujeres de 10 a 55 años, registro mensual","pág. 12"]]}],"flujo":["Quien identifique la muerte materna la reporta al responsable de vigilancia epidemiológica del establecimiento.","Se llena la FNIMM y se notifica dentro de las 24 h. En muerte hospitalaria reporta el médico jefe de guardia.","Se investiga con la FIEMM dentro de las 24 h de notificada. La investigación se inicia en el establecimiento donde ocurrió la muerte.","Si la certificación médica es insuficiente o no existe, o la muerte ocurre con menos de 24 h de permanencia y sin datos clínicos suficientes: autopsia verbal (FAVMM) obligatoria.","Si en la semana no hubo muertes maternas: notificación negativa semanal."],"flujo_nota":"Fuente: NTS 227-2025, págs. 8–9. Criterios de referencia inmediata: no especificado en la norma.","trampas":["Tardía vs. materna: pasados los 42 días es tardía y no entra en el cálculo de la razón o tasa de muerte materna.","Incidental no es materna: causa externa (accidente o violencia), aunque ocurra dentro de los 42 días.","«Muerte durante el embarazo, parto o puerperio» incluye cualquier causa; «muerte materna» excluye las accidentales e incidentales.","El suicidio en embarazo, parto o puerperio se clasifica como indirecta.","24 h es notificación e investigación (NTS 227). 30 días es auditoría médica (084) y llegada de datos al aplicativo (NTS 227).","Trimestral solo el comité nacional. Los demás niveles sesionan mensualmente.","Perinatal termina a los 7 días completos. Neonatal total llega a 28 días.","La Directiva 036 (RM 778-2016) está derogada por la NTS 227-2025."],"preguntas":[{"q":"En un C.S. I-3, una puérpera de 35 días fallece en su domicilio por shock séptico secundario a endometritis puerperal. Según la Directiva 084 y la NTS 227-2025, ¿cómo se clasifica y en qué plazo se notifica?","o":["Muerte materna indirecta, 48 horas","Muerte materna directa, extra-institucional, 24 horas","Muerte materna tardía, 72 horas","Muerte materna incidental, notificación semanal"],"k":1,"w":["Correcta: la endometritis es complicación obstétrica del puerperio (directa), dentro de los 42 días y fuera del establecimiento. La notificación es inmediata, dentro de las 24 h.","Falsa: la indirecta deriva de una enfermedad previa agravada por el embarazo, y el plazo es 24 h, no 48 h.","Falsa: tardía es después de los 42 días; aquí van 35.","Falsa: incidental es de causa externa, y la muerte materna no se notifica semanalmente."]},{"q":"El comité de un hospital solicita la auditoría médica de una muerte materna ocurrida en su institución. Según la Directiva 084, ¿qué plazos aplican?","o":["Auditoría en 24 horas; envío al regional en 72 horas","Auditoría a los 30 días del evento; envío al regional en máximo 7 días hábiles de culminada","Auditoría a los 7 días; envío al regional en 30 días calendario","Auditoría a los 15 días; envío al regional en 10 días hábiles"],"k":1,"w":["Falsa: son plazos de notificación, no de auditoría.","Correcta: Directiva 084, nivel hospital o instituto.","Falsa: invierte los números; los 30 días calendario son del informe regional al nivel nacional.","Falsa: los 10 días hábiles son para el acta del comité regional hacia el nivel nacional."]}],"pendientes":["Confirmar la vigencia de la Directiva 084 en El Peruano.","El texto digitalizado de la NTS 227 dice «24 boras»: confirmar las 24 h y los 15 + 15 días en el PDF original.","Los comités de la 084 se organizan por nivel (nacional, regional o de red, hospital), no por categoría I-1 a I-4."]},{"id":"nts-139-historia-clinica","match":"Resolución Ministerial N.° 214-2018-MINSA","code":"NTS N.° 139-MINSA/2018/DGAIN","title":"Gestión de la Historia Clínica","aprobada":"RM 214-2018/MINSA · deroga la RM 597-2006 (NT 022) y sus modificatorias RM 204-2015 y RM 078-2016","eje":"Cuidado integral de salud","estado":"REVIEW_REQUIRED","vigencia":"Aprobada en 2018. No se verificó derogatoria: confirmar la vigencia en El Peruano.","fuente":"","alerta":"La historia clínica es propiedad física de la IPRESS, pero la información clínica es del paciente. No mezcles los plazos: 5 días (copia o epicrisis), 48 h (egreso al archivo), 24 h (emergencia) y 72 h (préstamo para auditoría).","linea":{"titulo":"Vida de una historia clínica en el archivo","tramos":[{"t":"Archivo activo","s":"5 años desde la última atención","c":"verde","w":5},{"t":"Archivo pasivo","s":"15 años desde el traslado","c":"ambar","w":5},{"t":"Eliminación","s":"más de 20 años (5 + 15)","c":"gris","w":3}],"sellos":[{"t":"5 días","s":"Copia de HC o epicrisis","c":"rojo"},{"t":"48 h","s":"Egreso hospitalario: HC al archivo","c":"azul"},{"t":"24 h","s":"Emergencia: devolver la HC","c":"azul"},{"t":"40 años","s":"Cáncer ocupacional (mínimo)","c":"rojo"}],"nota":"Si un paciente con HC en archivo pasivo solicita atención, su HC vuelve al archivo activo."},"definiciones":[["Historia clínica","Documento médico legal en el que se registran los datos de identificación y de los procesos relacionados con la atención del paciente, en forma ordenada, integrada, secuencial e inmediata, refrendados con la firma manuscrita o digital. Las administran las IPRESS.","pág. 9"],["Historia clínica electrónica","Historia clínica registrada en forma unificada, personal, multimedia, refrendada con la firma digital del médico u otros profesionales de la salud.","pág. 9"],["Acto médico","Toda acción o disposición que realiza el médico en el ejercicio de la profesión: prevención, promoción, diagnóstico, terapéutica, pronóstico y rehabilitación, y lo que se derive directamente de ellos.","pág. 7"],["Epicrisis","Documento médico legal con el resumen de la historia clínica originada por el ingreso del paciente. Se entrega obligatoriamente a solicitud del paciente o su representante en un plazo máximo de 5 días. En defunción, se entrega con el egreso del difunto.","pág. 9"],["Archivo activo","Historias clínicas requeridas con frecuencia; permanecen hasta 5 años después de la última atención.","pág. 7"],["Archivo pasivo","Historias clínicas no requeridas por más de 5 años desde la última atención.","pág. 7"],["Archivo especial","Casos médico-legales y de interés científico o histórico; también las historias de pacientes con cáncer ocupacional.","pág. 7"],["Propiedad de la historia clínica","La HC y la base de datos son propiedad física de la IPRESS. La información clínica es propiedad del paciente (Ley 26842).","pág. 47"]],"plazos":[{"norma":"Entrega y conservación","filas":[["Copia autenticada de HC y epicrisis, a solicitud","Máximo 5 días. Menos de 48 h solo si se sustenta en la solicitud. El costo de reproducción lo asume el interesado","pág. 14 (4.2.14)"],["Informe de alta","Entrega obligatoria y gratuita","pág. 14 (4.2.15)"],["Conservación en archivo activo","5 años desde la fecha de la última atención","pág. 40"],["Conservación en archivo pasivo","15 años desde la fecha de traslado al pasivo; igual para pacientes fallecidos","pág. 40"],["Cáncer ocupacional","Mínimo 40 años, después de terminada la exposición","pág. 40"],["Evaluación para eliminación","HC del archivo común con más de 20 años (5 en activo + 15 en pasivo)","pág. 44"]]},{"norma":"Circuito de la historia clínica","filas":[["Consulta ambulatoria","La HC se devuelve el mismo día de la atención","pág. 50"],["Egreso del paciente hospitalizado","HC al archivo en un plazo no mayor de 48 h","pág. 50"],["HC solicitada por emergencia","Devolverla dentro de las 24 h siguientes (con salvedades)","pág. 50"],["HC prestada para informe especializado o auditoría médica","Devolver en un plazo no mayor de 72 h","pág. 43"]]}],"flujo":["Cada acto de atención se registra en la HC y se refrenda con firma manuscrita o digital.","Con el paciente hospitalizado, la enfermera responsable del servicio administra la HC.","Al retirar una HC del archivo se deja un tarjetón de reemplazo diferenciado, para seguirla y ubicarla.","Concluida la atención o trámite, la HC se devuelve de inmediato al archivo.","Si piden copia (paciente, Poder Judicial o Ministerio Público): copia autenticada en máximo 5 días."],"flujo_titulo":"3. Qué hacer con la historia clínica","flujo_nota":"Fuente: NTS 139, págs. 14, 40, 43 y 50.","trampas":["Cuatro plazos distintos: 5 días (copia o epicrisis), 48 h (egreso al archivo), 24 h (emergencia) y 72 h (préstamo para auditoría).","El archivo activo cuenta desde la última atención (5 años). El pasivo cuenta desde el traslado (15 años).","5 + 15 = 20 años para evaluar eliminación. Cáncer ocupacional es excepción: mínimo 40 años.","La copia de la HC la paga el interesado. El informe de alta es gratuito.","Propiedad dividida: la IPRESS es dueña de la carpeta física; el paciente es dueño de la información clínica.","La NTS 139 reemplaza a la NT 022 (RM 597-2006)."],"preguntas":[{"q":"Un paciente solicita copia autenticada de su historia clínica. Según la NTS 139, ¿cuál es el plazo máximo de entrega y quién asume el costo de reproducción?","o":["48 horas; lo asume la IPRESS","5 días; lo asume el interesado","15 días; es gratuita","72 horas; lo asume el interesado"],"k":1,"w":["Falsa: menos de 48 h solo se exige si se sustenta en la solicitud, y el costo es del interesado.","Correcta: plazo máximo de 5 días y costo de reproducción a cargo del interesado.","Falsa: 15 años es la conservación en archivo pasivo, no un plazo de entrega; y la copia no es gratuita.","Falsa: 72 h es el plazo para devolver una HC prestada para auditoría o informe."]},{"q":"La historia clínica de un paciente sin atención hace 6 años (no fallecido ni con cáncer ocupacional) ¿en qué archivo está y por cuánto tiempo más se conserva?","o":["Archivo activo; 5 años más","Archivo pasivo; 15 años desde su traslado","Archivo especial; 40 años","Se elimina de inmediato"],"k":1,"w":["Falsa: el activo guarda las HC hasta 5 años desde la última atención.","Correcta: pasada esa fecha se traslada al pasivo, donde se conserva 15 años desde el traslado.","Falsa: el especial es para casos médico-legales, de interés científico o cáncer ocupacional.","Falsa: la eliminación se evalúa tras más de 20 años (5 + 15)."]}],"pendientes":["Las páginas indicadas corresponden al PDF; confirmarlas contra el documento oficial.","El texto de la HC de emergencia (24 h) tiene salvedades que el texto digitalizado no deja leer completas.","Vigencia: confirmar en El Peruano (no se verificó derogatoria)."]},{"id":"nts-211-dengue","match":"Resolución Ministerial N.° 175-2024-MINSA","code":"NTS N.° 211-MINSA/DGIESP-2024","title":"Atención integral de pacientes con dengue en el Perú","aprobada":"RM 175-2024/MINSA","eje":"Salud pública","estado":"REVIEW_REQUIRED","vigencia":"Aprobada en 2024. No se verificó derogatoria: confirmar la vigencia en El Peruano.","fuente":"","alerta":"Se clasifica por signos: sin alarma, con alarma y grave. Y se decide el grupo de manejo (A, B1, B2, C). En el texto digitalizado el grupo del dengue grave aparece como «O» y luego como «C»: confirmarlo en el PDF.","linea":{"titulo":"Grupo de manejo según el cuadro clínico","tramos":[{"t":"Grupo A","s":"Sin signos de alarma · tratamiento en el hogar con supervisión médica","c":"verde","w":1},{"t":"Grupo B1","s":"Sin alarma + factores de riesgo · hospitalización","c":"ambar","w":1},{"t":"Grupo B2","s":"Con signos de alarma · hospitalización con líquidos IV","c":"ambar","w":1},{"t":"Grupo C","s":"Dengue grave · urgencia y referencia a UCI","c":"rojo","w":1}],"sellos":[{"t":"Inmediata","s":"Notificación obligatoria del caso probable","c":"rojo"},{"t":"≤ 7 días","s":"Fiebre del caso probable","c":"azul"},{"t":"14 días","s":"Antecedente de zona de transmisión","c":"azul"}]},"definiciones":[["Caso probable sin signos de alarma","Persona con fiebre de 7 días o menos, que reside o visitó áreas de transmisión o con infestación por Aedes aegypti en los 14 días previos al inicio de síntomas, y al menos 2 de: cefalea, mialgias, artralgias, dolor ocular o retro-ocular, náuseas o vómitos, rash (desde ~5.º día).","pág. 11 (5.2.1)"],["En niños","Todo niño con fiebre sin foco aparente de 7 días o menos, con el mismo antecedente epidemiológico.","pág. 11"],["Caso probable con signos de alarma","Una o más manifestaciones. Signos verificados: dolor abdominal intenso y continuo o dolor a la palpación, vómitos persistentes, sangrado de mucosas o piel, hepatomegalia mayor de 2 cm bajo el reborde costal derecho, aumento progresivo del hematocrito.","pág. 11–12 (5.2.2)"],["Caso probable de dengue grave","Persona con o sin signos de alarma que presenta al menos uno: signos de choque hipovolémico, síndrome de dificultad respiratoria por extravasación de plasma, o sangrado grave según criterio clínico.","pág. 12 (5.2.3)"],["Virus dengue (DENV)","Familia Flaviviridae, género Flavivirus, con cuatro serotipos: DENV-1, DENV-2, DENV-3 y DENV-4.","5.1.47"],["Reinfección","La reinfección por un serotipo diferente puede causar dengue grave.","pág. 21"]],"plazos":[{"norma":"Notificación y seguimiento","filas":[["Notificación de caso probable o confirmado","Obligatoria e inmediata, al personal de epidemiología del establecimiento o al inmediato superior","pág. 14 (5.3)"],["Ficha clínico-epidemiológica","Llenarla inmediatamente; no esperar resultado de laboratorio","pág. 14"],["Fiebre del caso probable","7 días o menos de evolución","pág. 11"],["Antecedente epidemiológico","Dentro de los 14 días antes del inicio de síntomas","pág. 11"],["Grupo A: evaluación","Diaria, cada 24 h como mínimo","pág. 31"],["Grupo A: seguimiento","Entre 24 y 48 h después del descenso de la fiebre sin antipiréticos","pág. 31"]]},{"norma":"Grupos de manejo","filas":[["Grupo A","Dengue sin signos de alarma: tratamiento en el hogar bajo supervisión médica","pág. 29"],["Grupo B1","Sin signos de alarma + factores asociados o riesgo: hospitalización en unidad de vigilancia clínica o ES con hospitalización","pág. 29"],["Grupo B2","Con signos de alarma: hospitalización para líquidos intravenosos","pág. 29"],["Grupo C (dengue grave)","Tratamiento de urgencia y referencia urgente a UCI","pág. 29"]]}],"flujo":["En el primer nivel se aplica un abordaje escalonado: evaluación general del paciente.","Medir e interpretar los signos vitales.","Notificar de inmediato el caso, sin esperar laboratorio.","Decidir el grupo de manejo (A, B1, B2 o C) según las manifestaciones y las circunstancias del paciente.","Reevaluar: el paciente puede pasar de un grupo a otro en muy poco tiempo."],"flujo_titulo":"3. Qué hacer en el primer nivel","flujo_nota":"Fuente: NTS 211, págs. 14 y 29–31.","trampas":["El dengue grave puede presentarse con o sin signos de alarma previos.","La notificación y la ficha no esperan el laboratorio.","B1 es sin signos de alarma pero con factores de riesgo. B2 es con signos de alarma. Ambos se hospitalizan.","7 días es la duración de la fiebre. 14 días es el antecedente de zona de transmisión.","Cuatro serotipos (DENV-1 a DENV-4); la reinfección por otro serotipo puede dar dengue grave.","El seguimiento del grupo A se cuenta desde que baja la fiebre sin antipiréticos."],"preguntas":[{"q":"Varón de 30 años, 4 días de fiebre, cefalea y mialgias, vive en zona de transmisión de dengue. No tiene signos de alarma ni factores de riesgo. Según la NTS 211, ¿qué grupo corresponde y cuándo se notifica?","o":["Grupo A, tratamiento en el hogar con supervisión médica; notificación inmediata","Grupo B2, hospitalización con líquidos IV; notificación inmediata","Grupo A; notificar cuando se confirme por laboratorio","Grupo C, referencia urgente a UCI; notificación inmediata"],"k":0,"w":["Correcta: caso probable sin signos de alarma (grupo A), y la notificación es inmediata.","Falsa: B2 es para dengue con signos de alarma.","Falsa: no se espera laboratorio para notificar ni para llenar la ficha.","Falsa: el grupo C es dengue grave, con choque, dificultad respiratoria o sangrado grave."]},{"q":"Paciente con dengue que presenta dolor abdominal intenso y vómitos persistentes. Según la NTS 211, ¿qué grupo y qué manejo corresponden?","o":["Grupo A, tratamiento en el hogar","Grupo B1, hospitalización por factores de riesgo","Grupo B2, hospitalización para líquidos intravenosos","Grupo C, urgencia y referencia a UCI"],"k":2,"w":["Falsa: el grupo A es sin signos de alarma.","Falsa: B1 es sin signos de alarma pero con factores asociados o riesgo.","Correcta: son signos de alarma, grupo B2.","Falsa: el grupo C requiere criterios de dengue grave (choque, dificultad respiratoria, sangrado grave)."]}],"pendientes":["Lista completa de signos de alarma: el texto digitalizado la corta; verificar en el PDF si hay más manifestaciones.","Grupo «C»: en un tramo del texto digitalizado aparece como «O»; confirmar en el PDF.","Pruebas de laboratorio (RT-PCR, NS1, IgM, inmunocromatográficas) y sus condiciones de uso: pendiente de ficha.","Vigencia: confirmar en El Peruano (no se verificó derogatoria)."]},{"id":"ds-026-2020-sa-pnms","match":"Decreto Supremo N.° 026-2020-SA","code":"Decreto Supremo N.° 026-2020-SA","title":"Política Nacional Multisectorial de Salud al 2030 «Perú, País Saludable»","aprobada":"DS 026-2020-SA (El Peruano, 24 de agosto de 2020)","eje":"Salud pública","estado":"REVIEW_REQUIRED","vigencia":"Horizonte 2030. No se verificó derogatoria: confirmar la vigencia en El Peruano.","fuente":"","alerta":"Puntos fijos de examen: los 3 objetivos prioritarios (OP1, OP2, OP3), quién conduce (MINSA), a quién reporta (CEPLAN) y el enfoque de curso de vida. Otras políticas tienen sus propios «OP»: no los mezcles.","linea":{"titulo":"Los 3 objetivos prioritarios","tramos":[{"t":"OP1","s":"Mejorar los hábitos, conductas y estilos de vida saludables de la población","c":"verde","w":1},{"t":"OP2","s":"Asegurar el acceso a servicios integrales de salud de calidad y oportunos","c":"azul","w":1},{"t":"OP3","s":"Mejorar las condiciones de vida que generan vulnerabilidad y riesgos en la salud","c":"ambar","w":1}],"sellos":[{"t":"MINSA","s":"Conduce, hace el seguimiento y la evaluación","c":"azul"},{"t":"CEPLAN","s":"Recibe los reportes de cumplimiento","c":"rojo"},{"t":"Sin fondos nuevos","s":"Se financia con el presupuesto de cada entidad","c":"azul"}]},"definiciones":[["Política Nacional Multisectorial de Salud (PNMS)","Política liderada por el MINSA, con enfoque territorial, formulada con los sectores responsables de los determinantes sociales de salud priorizados y con los gobiernos regionales y locales.","pág. 6"],["Enfoque y principios","Cuidado integral por curso de vida; derecho y equidad en salud; atención primaria de la salud (APS); determinación social de la salud; gestión territorial; Política de Igualdad de Género; Política Sectorial de Salud Intercultural; Política Nacional de Gestión ante Desastres.","pág. 6"],["OP1","Mejorar los hábitos, conductas y estilos de vida saludables de la población.","pág. 125–126"],["OP2","Asegurar el acceso a servicios integrales de salud de calidad y oportunos a la población.","pág. 125–126"],["OP3","Mejorar las condiciones de vida de la población que generan vulnerabilidad y riesgos en la salud.","pág. 125–126"],["Alineación","ODS 3 (salud y bienestar), 5, 6, 8 y 11; 13.ª Política de Estado «Acceso y cobertura universal de los servicios de salud y a la seguridad social».","pág. 6"]],"plazos":[{"norma":"Decreto Supremo (artículos)","filas":[["Art. 2 · Ámbito","Cumplimiento obligatorio para entidades del sector público, sector privado y sociedad civil, en lo que les sea aplicable","pág. 3"],["Art. 3 · Conducción","A cargo del Ministerio de Salud","pág. 3"],["Art. 4 · Seguimiento y evaluación","MINSA; remite los reportes de cumplimiento al CEPLAN. Las entidades responsables le brindan la información","pág. 3"],["Art. 5 · Implementación","Entidades responsables, mediante los planes del SINAPLAN, coordinando con el MINSA","pág. 3"],["Art. 6 · Financiamiento","Con cargo al presupuesto institucional de las entidades, sin recursos adicionales al Tesoro Público","pág. 3"]]},{"norma":"Lineamientos (lista parcial verificada)","filas":[["L 1.1 (OP1)","Mejorar los hábitos y conductas saludables de la población","pág. 126"],["L 1.2 (OP1)","Estrategias que incrementen la lactancia materna apropiada","pág. 126"],["L 1.4 (OP1)","Regular contenidos, etiquetado y publicidad de alimentos procesados","pág. 126"],["L 2.1 (OP2)","Fortalecer el servicio de telesalud para la población de zonas aisladas","pág. 126"],["L 2.4 (OP2)","Implementar Redes Integradas de Salud","pág. 126"],["L 2.5 (OP2)","Implementar el modelo de cuidado integral de salud por curso de vida","pág. 126"],["L 2.6 (OP2)","Garantizar la portabilidad del derecho de acceso a servicios de salud","pág. 126"]]}],"flujo":["El MINSA conduce la política.","Las entidades responsables de los objetivos y lineamientos la implementan mediante sus planes del SINAPLAN.","Esas entidades entregan información al MINSA para el seguimiento y la evaluación.","El MINSA remite los reportes de cumplimiento al CEPLAN."],"flujo_titulo":"3. Cómo se aplica","flujo_nota":"Fuente: DS 026-2020-SA, artículos 3 a 5, pág. 3.","trampas":["Son 3 objetivos prioritarios (OP1, OP2, OP3). Un «OP5» que aparezca en el texto pertenece a otra política (por ejemplo, la de Juventud).","Los reportes de cumplimiento van al CEPLAN.","Es multisectorial: obliga también al sector privado y a la sociedad civil, en lo que les corresponda.","No demanda recursos adicionales al Tesoro Público.","OP2 reúne telesalud, redes integradas, cuidado por curso de vida y portabilidad del derecho de acceso.","El enfoque central es el cuidado integral por curso de vida."],"preguntas":[{"q":"Según el DS 026-2020-SA, ¿quién conduce la Política Nacional Multisectorial de Salud al 2030 y a qué entidad se remiten los reportes de cumplimiento?","o":["El MINSA conduce; los reportes van al CEPLAN","La PCM conduce; los reportes van al MEF","El MINSA conduce; los reportes van a la PCM","Los gobiernos regionales conducen; los reportes van al MINSA"],"k":0,"w":["Correcta: artículos 3 y 4 del decreto.","Falsa: la conducción es del MINSA.","Falsa: el MINSA remite los reportes al CEPLAN, no a la PCM.","Falsa: las entidades responsables dan información al MINSA, que es quien conduce y reporta."]},{"q":"¿Cuál de los siguientes es un objetivo prioritario de la Política Nacional Multisectorial de Salud al 2030?","o":["Asegurar el acceso a servicios integrales de salud de calidad y oportunos a la población","Reducir la discriminación hacia la población joven en situación de vulnerabilidad","Reemplazar el aseguramiento público por el privado","Descentralizar el financiamiento de la salud a los gobiernos locales"],"k":0,"w":["Correcta: es el OP2.","Falsa: es un objetivo de otra política (la Política Nacional de Juventud).","Falsa: no es objetivo de la política.","Falsa: no es objetivo de la política; esta se financia con el presupuesto de cada entidad."]}],"pendientes":["Lineamientos de OP3 y algunos de OP1 y OP2: el texto digitalizado los corta; completar desde el PDF.","Metas, indicadores y servicios estándar de la política: pendiente de ficha.","Vigencia: confirmar en El Peruano (no se verificó derogatoria)."]},{"id":"nts-129-vih-pueblos-indigenas","match":"Resolución Ministerial N.° 1012-2016-MINSA","code":"NTS N.° 129-MINSA/2016/DGIESP","title":"Prevención y control de la infección por VIH en pueblos indígenas amazónicos, con pertinencia intercultural","aprobada":"RM 1012-2016/MINSA","eje":"Salud pública","estado":"REVIEW_REQUIRED","vigencia":"Aprobada en 2016. No se verificó derogatoria: confirmar la vigencia en El Peruano.","fuente":"","alerta":"Puntos fijos: consentimiento informado para la prueba y para iniciar el TARV (con intérprete), definiciones interculturales y rol de la brigada itinerante amazónica. Hay dos plazos de 24 h distintos: vacuna contra hepatitis B del recién nacido y comunicación de reacciones adversas graves.","linea":{"titulo":"Camino de la atención de una persona con VIH","tramos":[{"t":"1. Consejería","s":"Previa a la prueba, con pertinencia intercultural","c":"azul","w":1},{"t":"2. Consentimiento","s":"Informado; con intérprete salvo negativa expresa","c":"ambar","w":1},{"t":"3. Prueba de VIH","s":"Se ofrece al primer contacto a quien tiene o tuvo una ITS","c":"verde","w":1},{"t":"4. Inicio de TARV","s":"Solo con la Hoja de Consentimiento Informado firmada","c":"rojo","w":1}],"sellos":[{"t":"24 h","s":"Vacuna contra hepatitis B al recién nacido","c":"azul"},{"t":"24 h","s":"Reacción adversa grave: comunicar a DIRESA o GERESA","c":"rojo"},{"t":"15 días","s":"Reacciones leves o moderadas: máximo","c":"azul"}]},"definiciones":[["Interculturalidad","Conjunto de procesos políticos, sociales, jurídicos y educativos generados por la interacción de culturas en una relación de intercambios recíprocos, provocados por la presencia, en un mismo territorio, de grupos humanos con orígenes e historias diferentes.","pág. 8 (5.1.23)"],["Pertinencia intercultural","Cualidad de una intervención que la hace correspondiente a la realidad en que se desea ejecutar, porque es el resultado de un proceso dialógico entre culturas para construir el consenso de cómo implementarla.","pág. 8 (5.1.27)"],["Medicina tradicional","Conjunto de prácticas, enfoques, conocimientos y creencias sanitarias diversas que incorporan medicinas basadas en plantas, animales y/o minerales, terapias espirituales, técnicas manuales y ejercicios, para mantener el bienestar y prevenir, diagnosticar y tratar enfermedades.","pág. 8 (5.1.24)"],["Agente de medicina tradicional","Persona reconocida por la comunidad por su conocimiento de saberes ancestrales en la atención de la salud, aprendidos de sus antepasados o de otros miembros de la comunidad.","pág. 6 (5.1.5)"],["Agente comunitario de salud","Persona elegida o reconocida por su comunidad, que realiza acciones voluntarias de promoción de la salud y prevención de enfermedades, en coordinación con el personal de salud.","pág. 6 (5.1.4)"],["Brigada itinerante amazónica","Equipo de profesionales de la salud y de educadores pares o agentes comunitarios que brindan información, educación para la salud, consejería y búsqueda activa de casos de ITS y VIH en las zonas donde habitan los pueblos indígenas amazónicos, y vinculan a servicios de atención integral.","pág. 6 (5.1.8)"],["Mesa de diálogo intercultural","Espacio de trabajo del personal de salud, autoridades o líderes de la comunidad, agentes comunitarios y agentes de medicina tradicional (vegetalistas, curanderos, parteras, entre otros) para fomentar el diálogo intercultural.","pág. 8 (5.1.25)"],["Intérprete","Persona natural, capacitada para transmitir oralmente en una lengua enunciados emitidos originalmente en otra. La interpretación se realiza de manera simultánea.","pág. 8 (5.1.22)"],["Técnico de enfermería indígena","Personal de la salud bilingüe procedente de pueblos indígenas amazónicos.","pág. 9 (5.1.40)"],["Persona que vive con el VIH (PW)","Persona con pruebas de laboratorio confirmatorias de infección por el virus de la inmunodeficiencia humana.","pág. 8 (5.1.26)"],["Prueba rápida para VIH","Prueba de tamizaje (inmunoensayo enzimático rápido) para detectar anticuerpos contra el VIH en sangre capilar, suero, entre otras muestras.","pág. 8 (5.1.32)"],["Tratamiento antirretroviral (TARV)","Combinación de 3 o más medicamentos antirretrovirales que disminuye la carga viral en sangre hasta niveles indetectables.","pág. 9 (5.1.41)"]],"plazos":[{"norma":"Plazos","filas":[["Vacuna contra hepatitis B","Dentro de las 24 h de vida de todo recién nacido, según la NTS 080-2016/DGIESP v.04","pág. 18 (6.7.3.13)"],["Reacción adversa grave","Comunicar a la DIRESA o GERESA dentro de las 24 h de conocido el caso","pág. 18 (6.7.4.3)"],["Reacción adversa leve o moderada","Plazo no mayor de 15 días, en los formatos aprobados por la ANM","pág. 18 (6.7.4.3)"]]},{"norma":"Consentimiento informado","filas":[["Prueba de VIH a persona con ITS","Ofrecerla, previa consejería y consentimiento informado, al primer contacto con el personal de salud","pág. 15 (6.6.3.2)"],["Prueba en menor de edad","Se solicita el consentimiento informado y el asentimiento del menor","pág. 14"],["Inicio del TARV","Previa firma del consentimiento informado (Anexo 1), con explicación de riesgos, beneficios, derechos y obligaciones","pág. 15 (6.7.2.3)"],["Quién firma la hoja","El paciente, el intérprete (testigo) si fuera el caso, y el médico tratante","pág. 15"],["Paciente que no sabe leer ni escribir","Coloca su huella digital en la Hoja de Consentimiento Informado","pág. 15–16 (6.7.2.4)"]]}],"flujo":["Ofrecer consejería previa con pertinencia intercultural.","Pedir el consentimiento informado para la prueba, y asentimiento si es menor de edad.","Aplicar la prueba de tamizaje. Si es reactiva, se confirma con pruebas confirmatorias: así se define a la persona que vive con el VIH.","Para iniciar el TARV, firmar la Hoja de Consentimiento Informado con apoyo de intérprete, salvo negativa expresa del paciente.","Recién nacido: vacuna contra hepatitis B dentro de las 24 h de vida.","Reacciones adversas a los medicamentos: graves a DIRESA o GERESA en 24 h; leves o moderadas en máximo 15 días."],"flujo_titulo":"3. Qué hacer en el establecimiento","flujo_nota":"Fuente: NTS 129, págs. 14 a 18.","trampas":["Dos plazos de 24 h con asuntos distintos: vacuna de hepatitis B al recién nacido y reacciones adversas graves.","Reacciones leves o moderadas: 15 días, no 24 h.","Si no sabe leer ni escribir: huella digital en la hoja. El intérprete firma como testigo.","Interculturalidad no es lo mismo que pertinencia intercultural: la segunda es la cualidad de una intervención construida por diálogo entre culturas.","Agente comunitario de salud, agente de medicina tradicional y técnico de enfermería indígena son figuras distintas.","Persona que vive con el VIH: tiene pruebas confirmatorias, no solo una prueba rápida reactiva.","En menores de edad se pide consentimiento informado y también el asentimiento del menor."],"preguntas":[{"q":"Un establecimiento de una comunidad amazónica identifica una reacción adversa grave a un medicamento antirretroviral. Según la NTS 129, ¿a quién y en qué plazo se comunica?","o":["A la DIRESA o GERESA, dentro de las 24 horas de conocido el caso","A la DIRESA o GERESA, en un plazo no mayor de 15 días","A la ANM, en 72 horas","No se notifica si el paciente mejora"],"k":0,"w":["Correcta: las reacciones graves se comunican dentro de las 24 h de conocido el caso.","Falsa: 15 días es el plazo máximo para reacciones leves o moderadas.","Falsa: la norma establece 24 h para las graves y 15 días para las leves o moderadas, no 72 h.","Falsa: las notificaciones de sospechas de reacciones adversas se comunican en todos los casos."]},{"q":"Un paciente indígena amazónico que no sabe leer ni escribir va a iniciar tratamiento antirretroviral. Según la NTS 129, ¿cómo se documenta el consentimiento?","o":["Con consentimiento verbal, sin documento","Con su huella digital en la Hoja de Consentimiento Informado, con apoyo de intérprete salvo negativa expresa","Lo firma el jefe de la comunidad por él","Basta el asentimiento del agente comunitario"],"k":1,"w":["Falsa: el inicio del TARV requiere la firma del consentimiento informado.","Correcta: debe colocar su huella digital en la hoja.","Falsa: el consentimiento es del paciente; el intérprete actúa como testigo, no lo reemplaza.","Falsa: el asentimiento corresponde a menores de edad, y no reemplaza el consentimiento."]}],"pendientes":["Esquemas de medicamentos antirretrovirales y sus dosis: no incluidos en esta ficha; revisar en el PDF.","La norma remite a la NTS 108 y a la NTS 080 «vigentes o la que haga sus veces»: confirmar si fueron reemplazadas.","Vigencia: confirmar en El Peruano (no se verificó derogatoria)."]},{"id":"ds-005-2021-sa-telesalud","match":"Decreto Supremo N.° 005-2021-SA","code":"Decreto Supremo N.° 005-2021-SA","title":"Reglamento de la Ley N.° 30421, Ley Marco de Telesalud, y del Decreto Legislativo N.° 1490","aprobada":"DS 005-2021-SA (El Peruano, 23 de enero de 2021)","eje":"Cuidado integral de salud","estado":"REVIEW_REQUIRED","vigencia":"Existen normas posteriores de Telesalud (por ejemplo DS 019-2025-SA y RM 664-2025/MINSA): confirmar si modifican alguno de estos puntos.","fuente":"","alerta":"No confundir Telesalud con Telemedicina. Telesalud tiene 4 ejes; Telemedicina es el eje de prestación de servicios de salud. En emergencia nacional o alerta roja son obligatorios tres servicios, y no incluyen la teleconsulta.","linea":{"titulo":"Los ejes de la Telesalud (art. 13.2)","tramos":[{"t":"Telemedicina","s":"Prestación de los servicios de salud","c":"verde","w":1},{"t":"Telegestión","s":"Gestión de los servicios de salud","c":"azul","w":1},{"t":"Teleinformación, educación y comunicación","s":"A la población sobre los servicios de salud","c":"ambar","w":1},{"t":"Telecapacitación","s":"Fortalecimiento de capacidades del personal de salud","c":"gris","w":1}],"sellos":[{"t":"Emergencia","s":"Emergencia nacional o alerta roja: telemonitoreo, teleorientación y telegestión obligatorios","c":"rojo"},{"t":"RENIPRESS","s":"Las IPRESS que hacen Telesalud deben estar registradas","c":"azul"}]},"definiciones":[["Telemedicina","Provisión de servicios de salud a distancia en promoción, prevención, diagnóstico, tratamiento, recuperación, rehabilitación y cuidados paliativos, por personal de salud que utiliza las TIC, para facilitar el acceso a los servicios.","pág. 3"],["Teleconsulta","Consulta a distancia entre un profesional de la salud, en el marco de sus competencias, y una persona usuaria, mediante las TIC.","pág. 3"],["Teleinterconsulta","Consulta a distancia que realiza un personal de salud a un profesional de la salud para la atención de una persona usuaria, que puede estar presente o no.","pág. 3"],["Teleorientación","Acciones de un profesional de la salud, mediante las TIC, para dar al usuario consejería y asesoría con fines de promoción de la salud, prevención, recuperación o rehabilitación.","pág. 3"],["Telemonitoreo","Monitorización o seguimiento a distancia de la persona usuaria, en las IPRESS, transmitiendo su información clínica y, si el criterio médico lo amerita, parámetros biomédicos o exámenes auxiliares.","pág. 3"],["Teleapoyo al diagnóstico","Servicio de apoyo al diagnóstico a distancia mediante las TIC; incluye diagnóstico por imágenes, patología clínica y anatomía patológica, entre otros.","pág. 2"],["Telegestión","Aplicación de principios, conocimientos o métodos de la gestión de salud, mediante las TIC, en la planificación, organización, dirección y control de los servicios.","pág. 3"],["Teleinformación, educación y comunicación","Comunicación a distancia, mediante las TIC, para ampliar o precisar conocimientos sobre salud, dirigida a la población en general o a un sector de ella.","pág. 3"],["Telecapacitación","Proceso de enseñanza y aprendizaje mediante las TIC, realizado por personal especializado con las competencias necesarias.","pág. 2–3"],["Consentimiento informado","Autorización informada, libre y voluntaria que brinda el usuario, otorgándola o negándola, para el procedimiento o tratamiento de salud. El responsable del proceso es el médico tratante o el investigador.","pág. 1–2"]],"plazos":[{"norma":"Reglas del reglamento","filas":[["Ámbito (art. 2)","Se aplica a todo el sector salud","pág. 1"],["Estructura","4 títulos, 16 capítulos y 47 artículos","pág. 1"],["Ejes de Telesalud (art. 13.2)","Telemedicina, Telegestión, Teleinformación-Educación-Comunicación y Telecapacitación","pág. 5"],["Emergencia nacional o alerta roja (art. 14.3)","Las IPRESS brindan telemonitoreo, teleorientación y telegestión de manera obligatoria, según su capacidad resolutiva","pág. 5"],["Registro (art. 14.4)","Las IPRESS que realizan Telesalud requieren estar registradas en el RENIPRESS","pág. 5"],["Datos personales (art. 19.3)","La IPRESS obtiene el consentimiento para el tratamiento de los datos personales del usuario, incluida su transferencia a otra IPRESS, salvo excepciones","pág. 6"]]},{"norma":"Telemedicina","filas":[["Tipos (art. 31)","Teleconsulta, teleinterconsulta, teleorientación, telemonitoreo y otros que establezca el MINSA por RM","pág. 7"],["Servicios médicos de apoyo (art. 32.3)","Brindan tipos de telemedicina como servicios complementarios al diagnóstico y tratamiento. No realizan teleconsulta","pág. 7"],["Consentimiento informado (art. 36.2)","Lo requiere el médico en las situaciones de obligatoriedad del artículo 24 del Reglamento de la Ley 29414 (DS 027-2015-SA)","pág. 8"],["Prescripción (art. 38.1)","Puede ser farmacológica y no farmacológica, en teleconsulta, teleinterconsulta y telemonitoreo u otros que establezca el MINSA","pág. 8"]]}],"flujo":["La IPRESS que realiza Telesalud se registra en el RENIPRESS.","Los servicios de Telesalud se incorporan a la Cartera de Servicios de Salud, considerando la población adscrita y la demanda estimada.","Se obtiene el consentimiento para el tratamiento de los datos personales del usuario, incluida su transferencia a otra IPRESS si corresponde.","En telemedicina, el médico pide el consentimiento informado en los casos en que es obligatorio.","Ante emergencia nacional o alerta roja, se brindan telemonitoreo, teleorientación y telegestión según la capacidad resolutiva."],"flujo_titulo":"3. Cómo se aplica en una IPRESS","flujo_nota":"Fuente: DS 005-2021-SA, artículos 14, 19 y 36, págs. 5 a 8.","trampas":["Telesalud es el conjunto; Telemedicina es solo el eje de prestación de servicios de salud.","En emergencia nacional o alerta roja los tres servicios obligatorios son telemonitoreo, teleorientación y telegestión. La teleconsulta no está en esa lista.","Los servicios médicos de apoyo no realizan teleconsulta.","La teleinterconsulta es entre profesionales: un personal de salud consulta a un profesional, con la persona usuaria presente o no.","La teleorientación es consejería y asesoría; el telemonitoreo es seguimiento a distancia.","El reglamento desarrolla dos normas: la Ley 30421 y el Decreto Legislativo 1490."],"preguntas":[{"q":"Se declara emergencia nacional. Según el Reglamento de Telesalud, ¿qué servicios deben brindar obligatoriamente las IPRESS, según su capacidad resolutiva?","o":["Telemonitoreo, teleorientación y telegestión","Teleconsulta, teleinterconsulta y telecapacitación","Solo teleconsulta","Teleapoyo al diagnóstico y telegestión"],"k":0,"w":["Correcta: artículo 14.3 del reglamento.","Falsa: la lista de emergencia no incluye teleconsulta, teleinterconsulta ni telecapacitación.","Falsa: la teleconsulta no figura entre los servicios obligatorios en emergencia.","Falsa: el teleapoyo al diagnóstico no figura entre los obligatorios."]},{"q":"¿Cuál de estas definiciones corresponde a la teleinterconsulta?","o":["Consulta a distancia entre un profesional de la salud y una persona usuaria","Consulta a distancia que realiza un personal de salud a un profesional de la salud para la atención de una persona usuaria, que puede estar presente o no","Seguimiento a distancia de la persona usuaria con su información clínica","Consejería y asesoría a distancia para promoción y prevención"],"k":1,"w":["Falsa: esa es la teleconsulta.","Correcta: la teleinterconsulta es entre profesionales.","Falsa: esa es la definición de telemonitoreo.","Falsa: esa es la definición de teleorientación."]}],"pendientes":["Plazos de implementación y disposiciones complementarias finales: no incluidos; revisar en el PDF.","Normas posteriores de Telesalud pueden modificar o complementar este reglamento: confirmar.","Vigencia: confirmar en El Peruano (no se verificó derogatoria)."]}];
